import { string_scenery_phet_keyboardHelpDialog_faucetControls_faucetControls_StringProperty } from '../../strings/keyboardHelpDialog/faucetControls/faucetControls.js';
import { string_scenery_phet_keyboardHelpDialog_faucetControls_adjustFaucetFlow_StringProperty } from '../../strings/keyboardHelpDialog/faucetControls/adjustFaucetFlow.js';
import { string_scenery_phet_keyboardHelpDialog_faucetControls_adjustInSmallerSteps_StringProperty } from '../../strings/keyboardHelpDialog/faucetControls/adjustInSmallerSteps.js';
import { string_scenery_phet_keyboardHelpDialog_faucetControls_adjustInLargerSteps_StringProperty } from '../../strings/keyboardHelpDialog/faucetControls/adjustInLargerSteps.js';
import { string_scenery_phet_keyboardHelpDialog_faucetControls_openFaucetFully_StringProperty } from '../../strings/keyboardHelpDialog/faucetControls/openFaucetFully.js';
import { string_scenery_phet_keyboardHelpDialog_faucetControls_openFaucetBriefly_StringProperty } from '../../strings/keyboardHelpDialog/faucetControls/openFaucetBriefly.js';
import { string_scenery_phet_a11y_keyboardHelpDialog_faucetControls_adjustFaucetFlowDescription_StringProperty } from '../../strings/a11y/keyboardHelpDialog/faucetControls/adjustFaucetFlowDescription.js';
import { string_scenery_phet_a11y_keyboardHelpDialog_faucetControls_adjustInSmallerStepsDescription_StringProperty } from '../../strings/a11y/keyboardHelpDialog/faucetControls/adjustInSmallerStepsDescription.js';
import { string_scenery_phet_a11y_keyboardHelpDialog_faucetControls_adjustInLargerStepsDescription_StringProperty } from '../../strings/a11y/keyboardHelpDialog/faucetControls/adjustInLargerStepsDescription.js';
import { string_scenery_phet_a11y_keyboardHelpDialog_faucetControls_openFaucetFullyWithHomeDescription_StringProperty } from '../../strings/a11y/keyboardHelpDialog/faucetControls/openFaucetFullyWithHomeDescription.js';
import { string_scenery_phet_a11y_keyboardHelpDialog_faucetControls_openFaucetFullyDescription_StringProperty } from '../../strings/a11y/keyboardHelpDialog/faucetControls/openFaucetFullyDescription.js';
import { string_scenery_phet_a11y_keyboardHelpDialog_faucetControls_openFaucetBrieflyDescription_StringProperty } from '../../strings/a11y/keyboardHelpDialog/faucetControls/openFaucetBrieflyDescription.js';
import '../../../../globals.js';
import optionize from '../../../../phet-core/js/optionize.js';
import FaucetNode from '../../FaucetNode.js';
import sceneryPhet from '../../sceneryPhet.js';
import ArrowKeyNode from '../ArrowKeyNode.js';
import TextKeyNode from '../TextKeyNode.js';
import KeyboardHelpIconFactory from './KeyboardHelpIconFactory.js';
import KeyboardHelpSection, { KeyboardHelpSectionOptions } from './KeyboardHelpSection.js';
import KeyboardHelpSectionRow from './KeyboardHelpSectionRow.js';

const headingStringProperty = string_scenery_phet_keyboardHelpDialog_faucetControls_faucetControls_StringProperty;
const adjustFaucetFlowStringProperty = string_scenery_phet_keyboardHelpDialog_faucetControls_adjustFaucetFlow_StringProperty;
const adjustInSmallerStepsStringProperty = string_scenery_phet_keyboardHelpDialog_faucetControls_adjustInSmallerSteps_StringProperty;
const adjustInLargerStepsStringProperty = string_scenery_phet_keyboardHelpDialog_faucetControls_adjustInLargerSteps_StringProperty;
const openFaucetFullyStringProperty = string_scenery_phet_keyboardHelpDialog_faucetControls_openFaucetFully_StringProperty;
const openFaucetBrieflyStringProperty = string_scenery_phet_keyboardHelpDialog_faucetControls_openFaucetBriefly_StringProperty;

type SelfOptions = {
  tapToDispenseEnabled?: boolean; // Set this to true if any faucet in your sim has FaucetNodeOptions.tapToDispenseEnabled: true
  reverseAlternativeInput?: boolean; // Set this to true if your faucet Node reverses alternative input (because it faces left).
};

type FaucetControlsKeyboardHelpSectionOptions = SelfOptions & KeyboardHelpSectionOptions;

export default class FaucetControlsKeyboardHelpSection extends KeyboardHelpSection {

  public constructor( providedOptions?: FaucetControlsKeyboardHelpSectionOptions ) {

    const options = optionize<FaucetControlsKeyboardHelpSectionOptions, SelfOptions, KeyboardHelpSectionOptions>()( {

      // SelfOptions
      tapToDispenseEnabled: false,
      reverseAlternativeInput: false
    }, providedOptions );

    const leftRightArrowKeysIcon = KeyboardHelpIconFactory.iconRow( [ new ArrowKeyNode( 'left' ), new ArrowKeyNode( 'right' ) ] );

    // Adjust faucet flow [<] [>]
    const adjustFaucetFlowRow = KeyboardHelpSectionRow.labelWithIcon( adjustFaucetFlowStringProperty, leftRightArrowKeysIcon, {
      labelInnerContent: string_scenery_phet_a11y_keyboardHelpDialog_faucetControls_adjustFaucetFlowDescription_StringProperty
    } );

    // Adjust in smaller steps [Shift] + [<] [>]
    const adjustInSmallerStepsRow = KeyboardHelpSectionRow.labelWithIcon(
      adjustInSmallerStepsStringProperty,
      KeyboardHelpIconFactory.shiftPlusIcon( leftRightArrowKeysIcon ),
      {
        labelInnerContent: string_scenery_phet_a11y_keyboardHelpDialog_faucetControls_adjustInSmallerStepsDescription_StringProperty
      }
    );

    // Adjust in larger steps [Pg Up] [Pg Down]
    const adjustInLargerStepsRow = KeyboardHelpSectionRow.labelWithIcon(
      adjustInLargerStepsStringProperty,
      KeyboardHelpIconFactory.pageUpPageDownRowIcon(),
      {
        labelInnerContent: string_scenery_phet_a11y_keyboardHelpDialog_faucetControls_adjustInLargerStepsDescription_StringProperty
      }
    );

    let closeFaucetRow: KeyboardHelpSectionRow;
    let openFaucetFullyRow: KeyboardHelpSectionRow;
    if ( options.reverseAlternativeInput ) {

      // Close faucet [End] or [0]
      closeFaucetRow = KeyboardHelpSectionRow.fromHotkeyData( FaucetNode.CLOSE_FAUCET_REVERSED_HOTKEY_DATA );

      // Open faucet fully [Home]
      openFaucetFullyRow = KeyboardHelpSectionRow.labelWithIcon( openFaucetFullyStringProperty, TextKeyNode.home(), {
        labelInnerContent: string_scenery_phet_a11y_keyboardHelpDialog_faucetControls_openFaucetFullyWithHomeDescription_StringProperty
      } );
    }
    else {

      // Close faucet [Home] or [0]
      closeFaucetRow = KeyboardHelpSectionRow.fromHotkeyData( FaucetNode.CLOSE_FAUCET_HOTKEY_DATA );

      // Open faucet fully [End]
      openFaucetFullyRow = KeyboardHelpSectionRow.labelWithIcon( openFaucetFullyStringProperty, TextKeyNode.end(), {
        labelInnerContent: string_scenery_phet_a11y_keyboardHelpDialog_faucetControls_openFaucetFullyDescription_StringProperty
      } );
    }

    const content: KeyboardHelpSectionRow[] = [
      adjustFaucetFlowRow,
      adjustInSmallerStepsRow,
      adjustInLargerStepsRow,
      closeFaucetRow,
      openFaucetFullyRow
    ];

    // Open faucet briefly [Space] or [Enter]
    if ( options.tapToDispenseEnabled ) {
      const openFaucetBrieflyRow = KeyboardHelpSectionRow.labelWithIcon(
        openFaucetBrieflyStringProperty,
        KeyboardHelpIconFactory.iconOrIcon( TextKeyNode.space(), TextKeyNode.enter() ),
        {
          labelInnerContent: string_scenery_phet_a11y_keyboardHelpDialog_faucetControls_openFaucetBrieflyDescription_StringProperty
        }
      );
      content.push( openFaucetBrieflyRow );
    }

    super( headingStringProperty, content, options );
  }
}

sceneryPhet.register( 'FaucetControlsKeyboardHelpSection', FaucetControlsKeyboardHelpSection );